const body = $input.first().json.body || $input.first().json;

const fullName = body.fullName || body.name || 'Tran Thi B';
const email = body.email || 'b.tran@company.com';
const role = body.role || 'Software Engineer';
const department = body.department || 'Engineering';
const startDate = body.startDate || new Date(Date.now() + 7 * 86400000).toISOString().split('T')[0];

const onboardingId = `ONB-${Math.floor(100000 + Math.random() * 900000)}`;

return {
  onboardingId,
  fullName,
  email,
  role,
  department,
  startDate,
  createdAt: new Date().toISOString()
};

