const prev = $('Validate & Prepare Candidate').first().json;
const aiRaw = $input.first().json;

let text = '';
if (aiRaw.candidates?.[0]?.content?.parts?.[0]?.text) {
  text = aiRaw.candidates[0].content.parts[0].text;
} else {
  text = JSON.stringify(aiRaw);
}

text = text.replace(/```json\s*/gi, '').replace(/```\s*$/gi, '').trim();
let parsed = {};
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = {
    hardwareKit: ["Laptop tiêu chuẩn", "Chuột và bàn phím", "Màn hình phụ"],
    softwareAccounts: ["Google Workspace Email", "VPN Công ty", "Slack/Discord"],
    itChecklist: ["Cài đặt hệ điều hành", "Bàn giao tài khoản ngày đầu tiên"],
    welcomeSummary: "Chào mừng bạn đến với công ty!"
  };
}

return {
  onboardingId: prev.onboardingId,
  fullName: prev.fullName,
  email: prev.email,
  role: prev.role,
  department: prev.department,
  startDate: prev.startDate,
  hardwareKit: parsed.hardwareKit || [],
  softwareAccounts: parsed.softwareAccounts || [],
  itChecklist: parsed.itChecklist || [],
  welcomeSummary: parsed.welcomeSummary || '',
  status: "Pending Hardware Prep",
  createdAt: new Date().toISOString()
};

